column98:
={"Transformation information";
byrow(CQ3:CQ,
lambda(tID,
if(tID="","",
trim(iferror(
let(input_data,transpose(index({Transformations_Comp_cell_procedure,Transformations_Comp_cell_source,Transformations_Colony_counts,Transformations_Colony_sizes,Transformations_Colors,Transformations_Score_notes},
ID_TO_INDEX(tID))),
filtered_input_data,filter(input_data,input_data<>""),
join(" / ",filtered_input_data)
))))))}

column36:
=if(A3="","",
{"Calculated part sources:",
bycol(N3:W3,lambda(part,
if(or(part="",part="(construct complete)",$CK3<>""),"",
 let(rID_posn,iferror(ID_TO_INDEX(trim(regexextract(part,"(^r\d+ )|(>+r\d+)"))),FALSE),
 if(
  not(rID_posn),"part error!",
  let(status,lower(index(Registry_Status,rID_posn)),
  ifs(
   regexmatch(status,"queued"),"not cloned",
   regexmatch(status,"abandon"),"abandoned!",
   regexmatch(status,"held"),"held",
   regexmatch(status,"wait on stock"),"need stock",
   regexmatch(status,"complete|not construct"),
    let(stock_ID,index(Registry_Stock_to_use_for_GG,rID_posn),
      if(and(stock_ID<>"",index(Registry_Stock_to_use_for_GG_Conc,rID_posn)=""),
        ifs(
          index(Minipreps_m_Date_inoculated,ID_TO_INDEX(stock_ID))="",stock_ID&char(10)&"need inoc",
          index(Minipreps_m_Date_purified,ID_TO_INDEX(stock_ID))="",stock_ID&char(10)&"need prep",
          TRUE,stock_ID&char(10)&"need conc"),
        if(stock_ID="","need stock",stock_ID))),
   TRUE,""
)))))))
})

column60:
=if(or(A3="",CK3<>"",regexmatch(H3,"(hold)")),"",
if(BE3="","Set scale!",
if(BF3="","Set target nkµ!",
let(vols,
{settings_gDefaultLigaseVol/settings_gDefaultAssemblyScale*BE3,
settings_gDefaultREVol/settings_gDefaultAssemblyScale*BE3,
settings_gDefaultBufferVol/settings_gDefaultAssemblyScale*BE3,
arrayformula(iferror($BE3*$BF3/EC3:EL3,""))},
{"Calculated:",vols}))))
